ALTER TABLE machines ADD COLUMN terminalProfiles TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(terminalProfiles));
CREATE TABLE terminal_sessions(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects(id),machineId TEXT NOT NULL REFERENCES machines(id),profile TEXT NOT NULL,profileHash TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',controlOwner TEXT REFERENCES identities(id),controlEpoch INTEGER NOT NULL DEFAULT 0,leaseUntil INTEGER,cols INTEGER NOT NULL,rows INTEGER NOT NULL,snapshot TEXT,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE TABLE terminal_commands(id TEXT PRIMARY KEY,terminalId TEXT NOT NULL REFERENCES terminal_sessions(id),projectId TEXT NOT NULL REFERENCES projects(id),identityId TEXT NOT NULL REFERENCES identities(id),kind TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),controlEpoch INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'queued',createdAt INTEGER NOT NULL,dispatchedAt INTEGER,result TEXT);
CREATE INDEX terminal_command_queue ON terminal_commands(state,createdAt);
